import numpy as np

# Create a list of bounding boxes of connected components
def get_bboxes(grid):
    ones = np.argwhere(grid == 1)
    if len(ones) == 0:
        return []

    rows = sorted(set([r for r, c in ones]))
    cols = sorted(set([c for r, c in ones]))

    bboxes = []
    for rmin in rows:
        for rmax in rows:
            if rmax - rmin + 1 < 2:
                continue
            col_set = set([c for r, c in ones if rmin <= r <= rmax])
            col_set.discard(None)

 nrows = len(rows)
    bboxes = []
    for i in range(nrows):
        boxes = []
        for j in range(nrows):
            if i != j or j != i:
                boxes.append((i, j))
        for box in boxes:
            bboxes.append(box)
    return bboxes

